    "k472": "<span class=\"join-progress__dot\">2</span> <span class=\"join-progress__label\">Почему</span>",
    "k473": "<span class=\"join-progress__dot\">3</span> <span class=\"join-progress__label\">Сообщение</span>",
    "k474": "Шаг 1 / 3 · Кто вы",
    "k475": "Полное имя",
    "k476": "Эл. почта",
    "k477": "Организация и должность <span class=\"hint\">необязательно</span>",
